function serialise(kind){var f=FORMS[kind],o={company_id:cid(),updated_at:new Date().toISOString()};f.fields.forEach(function(x){var v=value('noise-f-'+x[1]);if((x[2]==='date'||x[2]==='datetime-local')&&v==='')v=null;if(x[2]==='number')v=v===''?null:Number(v);if(x[1]==='restriction_flag')v=v==='true';if(['payload','test_cases','parameters_json','bands_json','test_cases_json'].includes(x[1])){try{v=v?JSON.parse(v):(x[1].includes('cases')||x[1]==='bands_json'?[]:{});}catch(e){throw new Error(x[0]+' must contain valid JSON');}}o[x[1]]=v||(['effective_to','next_due_date','calibration_date','calibration_due_date','last_surveillance_date','next_surveillance_date','issued_at'].includes(x[1])?null:v);});return o;}
async function persist(tableName,row,id,ctx){ctx=ctx||editContext();assertContext(ctx);if(!canManage())throw new Error('Noise editing access required.');var options=id?{m:'PATCH',p:'return=representation',b:row}:{m:'POST',p:'return=representation',b:Object.assign({created_by:pid(),created_at:new Date().toISOString()},row)};var url='/'+tableName+(id?'?id=eq.'+encodeURIComponent(id)+'&company_id=eq.'+encodeURIComponent(ctx.company):'');var out=await api(url,options);assertContext(ctx);if(!out?.[0]?.id)throw new Error('The server did not confirm a saved record. Refresh the register to check before retrying.');return out[0];}
