function selector(title,name,rows,selected,multiple){var ids=Array.isArray(selected)?selected.map(String):[String(selected||'')],options=rows.map(function(x){return '<option value="'+h(x.id)+'" '+(ids.includes(String(x.id))?'selected':'')+'>'+h(x.label||x.code||x.name||x.id)+'</option>';}).join('');ids.filter(function(id){return id&&!rows.some(function(x){return String(x.id)===id;});}).forEach(function(id){options+='<option selected value="'+h(id)+'">Saved reference (not currently selectable)</option>';});return '<div class="noise-field full"><label for="noise-link-'+name+'">'+h(title)+'</label><input type="search" data-noise-filter="'+name+'" aria-label="Search '+h(title)+'" placeholder="Search records…"><select id="noise-link-'+name+'" '+(multiple?'multiple size="6"':'')+'>'+(!multiple?'<option value="">Not selected</option>':'')+options+'</select></div>';}
