function scopedRows(key){return (N.data[key]||[]).filter(function(row){return String(row.company_id)===String(cid());});}
function reportSources(type){var key=({survey:'surveys',measurement:'measurements',map:'maps',control:'controls',protection:'protectors',equipment:'instruments'})[type]||'assessments';return {key:key,rows:scopedRows(key).filter(function(x){return ['approved','accepted','published','verified','closed','available','assigned'].includes(x.status)&&!(key==='assessments'&&scopedRows(key).some(function(n){return n.code===x.code&&n.version_no>x.version_no&&n.status==='approved';}));}).map(function(x){return {id:x.id,label:(x.code||x.asset_code)+' · '+(x.subject_name||x.name||x.scope||'')+' · v'+(x.version_no||1)};})};}
